import { ok, fail } from './result.js';
import { getCustomer, normalizeId } from './customers.js';
import { invoiceTotals } from './invoices.js';
import { balanceDue } from './payments.js';

/**
 * Generate a customer statement for invoices due on or before a given date.
 * @param {string} customerId - Customer ID
 * @param {Array<{ customerId: string, issueDate: string, dueDate?: string, status: string, lines: Array, voucher?: any, payments?: Array }>} invoices - All invoices
 * @param {string} asOf - Statement date (YYYY-MM-DD)
 * @returns {{ ok: true, value: { customerId: string, invoices: Array, totalDue: number } } | { ok: false, error: string }}
 */
export function statement(customerId, invoices, asOf) {
  // Normalize customer ID
  const normalizedCustomerId = normalizeId(customerId);

  // Validate customer exists
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  // Filter and transform invoices
  const statementInvoices = invoices
    .filter((invoice) => {
      // Check customer matches
      if (invoice.customerId !== normalizedCustomerId) return false;
      // Check status is issued or partially_paid
      if (!['issued', 'partially_paid', 'paid'].includes(invoice.status)) return false;
      // Check issueDate is on or before asOf
      if (invoice.issueDate > asOf) return false;
      return true;
    })
    .map((invoice) => {
      const totals = invoiceTotals(invoice);
      const due = balanceDue(invoice);
      return {
        number: invoice.number,
        issueDate: invoice.issueDate,
        dueDate: invoice.dueDate,
        total: totals.total,
        due,
      };
    })
    .sort((a, b) => a.issueDate.localeCompare(b.issueDate));

  // Calculate total due
  const totalDue = statementInvoices.reduce((sum, inv) => sum + inv.due, 0);

  return ok({
    customerId: normalizedCustomerId,
    invoices: statementInvoices,
    totalDue,
  });
}

